/**
 * Ported from digital-pedal-platform's `tools/schgen/generateFiles.ts`, and DIVERGED from it by
 * Task 16 of the M1 schematic-authoring plan: the generated file set gains `MANIFEST.json`
 * (spec §2.1).
 *
 * It no longer re-derives from the pedals source. `tests/schgen/port-fidelity.test.ts` does not
 * byte-check it, re-running `tools/schgen/port.ts` will NOT refresh it: **edit this file**. Its
 * `diverged` entry in `tools/schgen/port-manifest.json` carries the reason; see
 * `lib/schgen/README.md` and `docs/known-gaps.md`.
 *
 * **WHY THE DIVERGENCE IS HERE AND NOT IN `generate.ts`, which would have kept the byte-check.**
 * `generate` could have added one entry to the map `generatedFiles` returns, and that was weighed:
 * `staleFiles` and `writeGeneration` both read the map, so end to end it would have worked. It is
 * NOT done, because `generatedFiles`'s contract is *the generated file set* and a second caller of
 * it would then produce a set with no manifest in it - two places to keep correct, which
 * `CLAUDE.md` forbids, in exchange for one byte-check. The cost of the divergence is recorded in
 * `docs/known-gaps.md` rather than paid silently.
 */

/**
 * The generated file set, staleness against disk (read-only) and the one writer.
 */
import fs from "node:fs";
import path from "node:path";
import { repoRoot } from "../repo.ts";
import type { LoadedDesign } from "../../lib/schgen/design.ts";
import type { Circuit } from "../../lib/schgen/ir/types.ts";
import { serializeRefLock, type Annotation } from "../../lib/schgen/lock/annotate.ts";
import { renderRefmap } from "../../lib/schgen/lock/refmap.ts";
import { libraryDigest, type VersionLock } from "../../lib/schgen/lock/version-lock.ts";
import { emitContext, emitRoot, emitSheet } from "../../lib/schgen/render/emit.ts";
import { exclusionKey } from "../../lib/schgen/render/erc-exclusions.ts";
import type { SymbolResolver } from "../../lib/schgen/render/library.ts";
import { libTable, projectFile } from "../../lib/schgen/render/project.ts";
import type { SheetDrawing } from "../../lib/schgen/render/sheet-types.ts";
import { buildReport, renderReport } from "../../lib/schgen/report.ts";
import { MANIFEST_FILE, buildManifest, manifestInputsOf, serializeManifest, type ManifestSources } from "../../lib/schgen/manifest.ts";

export const REFS_LOCK = "refs.lock.json";
export const VERSION_LOCK = "schgen.lock.json";

const posix = (p: string): string => p.split(path.sep).join("/");

/** The design path as a user types it from the current directory. */
function designArg(d: LoadedDesign): string {
  return path.relative(process.cwd(), d.file);
}

export function initHint(d: LoadedDesign): string {
  return `run pnpm schgen generate --init ${designArg(d)} to create it`;
}

/** Project libraries as ${KIPRJMOD}-relative uris from outDir. */
function projectLibs(d: LoadedDesign, libs: Readonly<Record<string, string>>): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [nick, p] of Object.entries(libs)) out[nick] = `\${KIPRJMOD}/${posix(path.relative(d.outDir, path.resolve(d.dir, p)))}`;
  return out;
}

/**
 * KiCad's S-expression format keeps no comments across a save, so the title block's comment
 * fields carry the provenance and versions (they also print on the PDF). The design path is
 * relative to the root of the design's own repository, so the bytes do not depend on the
 * working directory.
 */
function titleComments(d: LoadedDesign, versions: VersionLock): string[] {
  return [
    `Generated by schgen from ${posix(path.relative(repoRoot(d.dir), d.file))}; do not edit`,
    `KiCad ${versions.kicad}; stock libraries ${libraryDigest(versions)}`,
  ];
}

export interface FileInputs {
  readonly design: LoadedDesign;
  readonly circuit: Circuit;
  readonly symbols: SymbolResolver;
  readonly annotation: Annotation;
  readonly versions: VersionLock;
  /** schgen.lock.json exactly as recorded: an existing clean lock's bytes, or the serialized current versions. */
  readonly versionLockText: string;
  readonly drawings: readonly SheetDrawing[];
  /**
   * Spec §2.1's five manifest INPUTS. The sixth - the generated set - is assembled here, because
   * the manifest hashes the files this function produces and is itself one of them.
   */
  readonly manifestSources: ManifestSources;
}

export function generatedFiles(x: FileInputs): Map<string, string> {
  const d = x.design;
  const project = d.spec.project;
  const ctx = emitContext(project, x.circuit, x.symbols, x.annotation.refs, titleComments(d, x.versions));
  const files = new Map<string, string>();
  const add = (name: string, text: string): void => {
    if (files.has(name)) throw new Error(`generate: two generated files are named ${name}`);
    files.set(name, text);
  };
  add(`${project}.kicad_sch`, emitRoot(ctx));
  for (const drawing of x.drawings) add(drawing.sheet.file, emitSheet(drawing, ctx));
  // Exclusion keys need the placed pin positions, so they are built here where the drawings exist (A2 Task 15).
  const exclusions = d.spec.ercExclusions.map((exclusion) => ({ key: exclusionKey(exclusion, ctx, x.drawings), exclusion }));
  add(`${project}.kicad_pro`, projectFile(project, exclusions));
  add("sym-lib-table", libTable("sym", projectLibs(d, d.spec.symbolLibs)));
  add("fp-lib-table", libTable("fp", projectLibs(d, d.spec.footprintLibs)));
  add(REFS_LOCK, serializeRefLock(x.annotation.lock));
  add(VERSION_LOCK, x.versionLockText);
  add("REFMAP.md", renderRefmap(x.circuit, x.annotation));
  add("RENDER-REPORT.md", renderReport(buildReport(x.circuit, x.drawings)));
  // LAST, and after every other file: spec §2.1's manifest hashes the generated set, so it can
  // only be built once that set is complete. `manifestInputsOf` excludes MANIFEST.json itself -
  // one rule, shared with tools/schgen/verify.ts, so the producer and the verifier cannot disagree
  // about what is hashed.
  add(MANIFEST_FILE, serializeManifest(buildManifest(manifestInputsOf(x.manifestSources, files))));
  return files;
}

interface FilesOnly {
  readonly files: ReadonlyMap<string, string>;
}

/** Every generated file missing or differing on disk, and every .kicad_sch in outDir schgen did not produce. Never writes. */
export function staleFiles(d: LoadedDesign, g: FilesOnly): string[] {
  const out: string[] = [];
  for (const name of [...g.files.keys()].sort()) {
    const file = path.join(d.outDir, name);
    const onDisk = fs.existsSync(file) ? fs.readFileSync(file, "utf8") : null;
    if (onDisk !== g.files.get(name)) out.push(`${name} is stale; run pnpm schgen generate ${designArg(d)}`);
  }
  const present = fs.existsSync(d.outDir) ? fs.readdirSync(d.outDir) : [];
  for (const name of present.filter((f) => f.endsWith(".kicad_sch") && !g.files.has(f)).sort()) {
    out.push(`${name} is not generated by schgen; remove it`);
  }
  return out;
}

/** The only writer: every generated file under outDir. Returns the written paths. */
export function writeGeneration(d: LoadedDesign, g: FilesOnly): string[] {
  const targets = [...g.files].map(([name, text]) => {
    const file = path.resolve(d.outDir, name);
    const rel = path.relative(d.outDir, file);
    if (rel === "" || rel.startsWith("..") || path.isAbsolute(rel)) {
      throw new Error(`${name} would be written outside ${d.outDir}; nothing was written`);
    }
    return { file, text };
  });
  fs.mkdirSync(d.outDir, { recursive: true });
  for (const { file, text } of targets) {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, text);
  }
  return targets.map((t) => t.file);
}
